function matches(p,f=filters,q=query,except=''){return (!q||[p.name,p.sku,p.barcode||'',p.type||'',p.dept||''].join(' ').toLowerCase().includes(q.toLowerCase()))&&Object.entries(f).every(([k,vals])=>{if(k===except||!vals.length)return true;if(isNumeric(k)){const n=furniture.numeric(p,k),[min,max]=vals;return n!==null&&(!min||n>=Number(min))&&(!max||n<=Number(max));}return facetValues(p,k).some(v=>vals.includes(String(v)))||(!furniture&&k==='type'&&context?.dept==='Soft Furnishings'&&vals.some(v=>window.GalleryCatalogueRouting.routeMatch(p,v)));})}
