function renderFilters(){const container=$('#mirror-filters');if(!container)return;const openFields=new Set($$('details[data-facet][open]').map(d=>d.dataset.facet));const initial=!container.dataset.ready;container.dataset.ready='1';container.classList.toggle('furniture-filters',!!context?.furniture);container.classList.toggle('art-filters',!!context?.art);container.classList.toggle('lighting-filters',!!context?.lighting);container.classList.toggle('textiles-filters',!!context?.textiles);container.classList.toggle('accessories-filters',!!context?.accessories);container.classList.toggle('artbeat-filters',!!context?.artbeat);container.classList.toggle('made-to-order-filters',!!context?.madeToOrder);container.classList.toggle('clocks-filters',!!context?.clocks);container.innerHTML='<div class="filter-panel-head"><strong>'+esc(context?.filterHeading||'Filter products')+'</strong><button class="filter-close" type="button" aria-label="Close filters">×</button></div>'+Object.entries(labels).filter(([k])=>!(context?.clocks&&k==='size')).map(([k,label])=>{const open=initial?k===Object.keys(labels).find(key=>!(context?.clocks&&key==='size')):openFields.has(k);let content;if(isNumeric(k)){const available=products.some(p=>furniture.numeric(p,k)!==null),unit=context?.numericUnits?.[k]||(k==='price'?'£':'mm');content=`<div class="spec-range">${['Min','Max'].map((bound,i)=>`<label for="${k}-${bound}"><span>${bound}</span><input id="${k}-${bound}" type="number" min="0" step="${k==='price'?'0.01':'1'}" inputmode="decimal" data-facet="${k}" data-bound="${i}" value="${esc(filters[k]?.[i]||'')}" aria-label="${label} ${bound.toLowerCase()} in ${k==='price'?'pounds':context?.numericUnits?.[k]==='W'?'watts':'millimetres'}" ${available?'':'disabled'}><span>${unit}</span></label>`).join('<span aria-hidden="true">–</span>')}</div>${available?'':`<p class="facet-unavailable">${k==='price'?'Trade prices':'Measurements in mm'} not supplied.</p>`}`;if(context?.clocks&&k==='width'){content='<p class="facet-unavailable">Width / Diameter (mm)</p>'+content;content+=['Small','Medium','Large','Oversized'].filter(v=>products.some(p=>facetValues(p,'size').includes(v))).map(v=>{const n=products.filter(p=>facetValues(p,'size').includes(v)&&matches(p,filters,query,'size')).length;return `<label><input type="checkbox" data-facet="size" value="${v}" ${filters.size?.includes(v)?'checked':''} ${!n&&!filters.size?.includes(v)?'disabled':''}>${v}<small>${n}</small></label>`}).join('');}}else{let values=[...new Set([...(context?.facetOptions?.[k]||[]),...products.flatMap(p=>facetValues(p,k)).filter(v=>v!==undefined&&v!==null&&v!==''&&v!=='Not specified'&&v!=='Not supplied')])];if(k==='size'&&!context)values=['Small','Medium','Large','Extra large'].filter(v=>values.includes(v));if(context?.hideEmptyValues)values=values.filter(v=>products.some(p=>facetValues(p,k).includes(v)));content=values.length?values.map(v=>{const n=products.filter(p=>facetValues(p,k).includes(v)&&matches(p,filters,query,k)).length,selected=filters[k]?.includes(String(v));return `<label><input type="checkbox" data-facet="${k}" value="${esc(v)}" ${selected?'checked':''} ${n===0&&!selected?'disabled':''}>${esc(v)}<small>${n}</small></label>`}).join(''):'<p class="facet-unavailable">'+esc(context?.facetNotes?.[k]||'Specification not supplied.')+'</p>'; }return `<details data-facet="${k}" ${open?'open':''}><summary>${label}<span aria-hidden="true">+</span></summary>${content}</details>`}).join('')+(context?.omitFilterNote?'':context?.filterNote?'<p class="filter-data-note">'+esc(context.filterNote)+'</p>':furniture?'<p class="filter-data-note">Dimensions use millimetres. Options without sample specifications are unavailable.</p>':context?'<p class="filter-data-note">Filters use the available sample attributes. Verify availability against Gallery before ordering.</p>':'<p class="filter-data-note">Size bands use the longest supplied dimension: Small ≤60 cm, Medium 61–90 cm, Large 91–120 cm, Extra large &gt;120 cm. Stock labels are supplied sample values.</p>')+'<button class="mobile-apply" type="button">Show products</button>';container.querySelector('.filter-close').addEventListener('click',closePanel);container.querySelector('.mobile-apply').addEventListener('click',closePanel)}
if(params.get('stock'))filters.availability=[params.get('stock')];
function syncFilterToggle(){const button=$('.filter-toggle'),panel=$('#mirror-filters');if(!button||!panel)return;const mobile=matchMedia('(max-width:900px)').matches,collapsed=!mobile&&$('.plp-layout').classList.contains('filters-hidden');$('.filter-toggle-label').textContent=mobile?'Filters':collapsed?'Show filters':'Hide filters';button.classList.toggle('is-collapsed',collapsed);button.setAttribute('aria-expanded',String(mobile?panel.classList.contains('is-open'):!collapsed));button.title=mobile?'Open product filters':collapsed?'Show product filters':'Hide filters and expand product view';panel.inert=collapsed;if(!mobile){panel.removeAttribute('role');panel.removeAttribute('aria-modal');panel.setAttribute('aria-hidden',String(collapsed))}}
function renderMirrors(){if(!$('#mirror-grid'))return;const result=selectProducts();$('#mirror-grid').innerHTML=result.length?result.map(card).join(''):`<div class="empty-results"><h2>${products.length?'No matching sample products':'Approved range data needed'}</h2><p>${products.length?'Try removing a filter or changing your search.':'This category is proposed for the menu. Product coverage must be validated against Gallery’s active range.'}</p><button data-clear-filters type="button">Clear filters</button></div>`;$('.plp-count strong').textContent=result.length;$('.result-topline span').textContent=`Showing ${result.length} of ${products.length} sample products`;const active=Object.entries(filters).flatMap(([k,vals])=>(isNumeric(k)?vals.map((v,i)=>v?`${i===0?'Min':'Max'} ${labels[k]}: ${v} ${context?.numericUnits?.[k]||(k==='price'?'£':'mm')}`:'').filter(Boolean):vals).map(v=>`<button data-remove-facet="${k}" data-value="${esc(v)}" aria-label="Remove ${esc(labels[k])}: ${esc(v)}">${esc(v)} <span aria-hidden="true">×</span></button>`));if(query)active.push(`<button data-clear-search aria-label="Remove search">Search: ${esc(query)} ×</button>`);$('#applied-filters').innerHTML=active.join('')+(active.length?'<button data-clear-filters class="clear-filters">Clear all</button>':'');$('.filter-count').textContent=active.length;$('.filter-count').hidden=!active.length;$('.filter-count').setAttribute('aria-label',active.length+' applied filters');syncFilterToggle();$('#mirror-sort').value=sort;renderFilters();$('.mobile-apply').textContent=`Show ${result.length} products`;if(products.length&&products.every(p=>p.realGalleryMirror||p.realGalleryArt||p.demoLighting)){$('.load-more span').textContent=`${result.length} of ${result.length} matching products`;$('.load-more .progress i').style.width='100%';$('.load-more button').textContent='All products shown';$('.load-more button').disabled=true;}$$('.subcategory-strip a').forEach(a=>{if(context)return;const p=new URL(a.href).searchParams;const match=Array.from(p.entries()).every(([k,v])=>filters[k]?.includes(v));a.classList.toggle('is-active',p.size?match:Object.values(filters).every(v=>!v.length));a.setAttribute('aria-current',a.classList.contains('is-active')?'page':'false')});if(!context&&params.get('route')==='new'&&!$('.route-note')){const note=document.createElement('p');note.className='route-note';note.textContent='Newness dates were not supplied. This preview shows the available mirror sample range.';$('.plp-toolbar').before(note)}updateUrl()}
if($('#mirror-grid')){
 renderMirrors();$('.filter-toggle').setAttribute('aria-controls','mirror-filters');syncFilterToggle();$('.filter-toggle').addEventListener('click',e=>{if(matchMedia('(max-width:900px)').matches)openPanel($('#mirror-filters'),e.currentTarget,$('.filter-backdrop'));else{$('.plp-layout').classList.toggle('filters-hidden');syncFilterToggle()}});matchMedia('(max-width:900px)').addEventListener('change',()=>{closePanel();syncFilterToggle()});$('.filter-backdrop')?.addEventListener('click',closePanel);$('#mirror-sort').addEventListener('change',e=>{sort=e.target.value;renderMirrors()});const gridViewButtons=$$('.view-control[data-grid-view]');function setGridView(compact){$('#mirror-grid').classList.toggle('compact-grid',compact);$('#mirror-grid').classList.toggle('large-grid',!compact);gridViewButtons.forEach(button=>button.setAttribute('aria-pressed',String((button.dataset.gridView==='compact')===compact)))}setGridView(window.matchMedia('(max-width:700px)').matches);gridViewButtons.forEach(button=>button.addEventListener('click',()=>setGridView(button.dataset.gridView==='compact')));$('#mirror-filters').addEventListener('change',e=>{if(!e.target.matches('input[data-facet]'))return;const k=e.target.dataset.facet,v=e.target.value,selected=filters[k]||[];if(isNumeric(k)){const next=[...(filters[k]||['',''])];next[Number(e.target.dataset.bound)]=v!==''&&Number(v)>=0?v:'';filters[k]=next.some(Boolean)?next:[];renderMirrors();$('#mirror-filters').querySelector(`input[data-facet="${k}"][data-bound="${e.target.dataset.bound}"]`)?.focus();return;}filters[k]=e.target.checked?[...selected,v]:selected.filter(x=>x!==v);renderMirrors();Array.from($('#mirror-filters').querySelectorAll('input[data-facet]')).find(input=>input.dataset.facet===k&&input.value===v)?.focus()});
}
