function showPhoto(i){if(!product||!product.images.length)return;photoIndex=Math.max(0,Math.min(product.images.length-1,i));$('#main-product-image').src=product.images[photoIndex];$('#main-product-image').alt=product.name+' — '+(product.imageLabel||'illustrative room reference');$$('.thumb').forEach((b,j)=>{b.classList.toggle('is-active',j===photoIndex);b.setAttribute('aria-pressed',String(j===photoIndex))});$$('[data-image-index]').forEach((b,j)=>b.setAttribute('aria-current',String(j===photoIndex)));$('.gallery-prev').disabled=photoIndex===0;$('.gallery-next').disabled=photoIndex===product.images.length-1}
